import numpy as np
lines=open('opt2.xyz').read().strip().split('\n')
n=int(lines[0]); sym=[];xyz=[]
for l in lines[2:2+n]:
    p=l.split(); sym.append(p[0]); xyz.append([float(x) for x in p[1:4]])
xyz=np.array(xyz)
pd=18
for i,lab in [(1,'Sa'),(9,'Sb'),(16,'Na'),(17,'Nb'),(19,'CMe'),(20,'Cl')]:
    print(lab,sym[i],round(np.linalg.norm(xyz[i]-xyz[pd]),3))
def ang(a,b,c):
    v1=xyz[a]-xyz[b]; v2=xyz[c]-xyz[b]
    return round(float(np.degrees(np.arccos(v1@v2/np.linalg.norm(v1)/np.linalg.norm(v2)))),1)
print('S-Pd-S',ang(1,18,9),'N-Pd-N',ang(16,18,17),'C-Pd-Cl',ang(19,18,20))
print('trans:',ang(16,18,20),ang(17,18,19))
# connectivity check
import itertools
cov={'C':0.76,'N':0.71,'S':1.05,'H':0.31,'Cl':1.02,'Pd':1.39}
bl=[]
for i,j in itertools.combinations(range(n),2):
    d=np.linalg.norm(xyz[i]-xyz[j])
    if d< (cov[sym[i]]+cov[sym[j]])*1.3: bl.append((i,j,sym[i],sym[j],round(d,2)))
print(len(bl))
for b in bl: print(b)
